// src/pages/Leads.js (PHIÊN BẢN HOÀN THIỆN CUỐI CÙNG)

import React, { useState, useEffect } from "react";
import api from "@landinghub/api";
import LeadKanban from "../components/LeadKanban";
import LeadList from "../components/LeadList";
import LeadEditModal from "../components/LeadEditModal";
import LandingFormModal from "../components/LandingFormModal";
import '../styles/leads.css';

const Leads = () => {
  const [leads, setLeads] = useState([]);
  const [view, setView] = useState("kanban");
  const [editingLead, setEditingLead] = useState(null);
  const [showAddForm, setShowAddForm] = useState(false);

  useEffect(() => {
    const fetchLeads = async () => {
      try {
        const res = await api.get("/api/leads");
        setLeads(Array.isArray(res.data) ? res.data : []);
      } catch (err) {
        console.error("Fetch leads error:", err);
      }
    };
    fetchLeads();
  }, []);

  const handleAddLead = async (formData) => {
    try {
      const res = await api.post("/api/leads", formData);
      setLeads(prevLeads => [...prevLeads, res.data]);
    } catch (err) {
      console.error("Add lead error:", err);
    }
  };

  const handleDeleteLead = async (id) => {
    if (!window.confirm("Bạn có chắc chắn muốn xóa lead này?")) return;
    try {
      await api.delete(`/api/leads/${id}`);
      setLeads(leads.filter((l) => l._id !== id));
    } catch (err) {
      console.error("Delete lead error:", err);
    }
  };
  
  const onDrop = async (newStatus, lead) => {
    if (!lead || lead.status === newStatus) return;
  
    let newScore = lead.score || 0;
    let activity = null;
  
    if (newStatus === 'processing' && lead.status === 'new') newScore += 1;
    else if (newStatus === 'converted') newScore += 2;
  
    const finalScore = Math.min(newScore, 5);
    const updatedLeadData = { ...lead, status: newStatus, score: finalScore };
    if(activity) updatedLeadData.activities = [...(lead.activities || []), activity];
    
    setLeads(prev => prev.map(l => l._id === lead._id ? updatedLeadData : l));
  
    try {
      await api.put(`/api/leads/${lead._id}`, { status: newStatus, score: finalScore });
      if (activity) await api.post(`/api/leads/${lead._id}/activities`, activity);
    } catch (err) {
      console.error("Update lead on drop error:", err);
      setLeads(prev => prev.map(l => l._id === lead._id ? lead : l));
    }
  };

  const handleSaveEdit = async (formData) => {
    try {
      const res = await api.put(`/api/leads/${formData._id}`, formData);
      setLeads(prev => prev.map((l) => (l._id === formData._id ? res.data : l)));
      setEditingLead(null);
    } catch (err) {
      console.error("Update lead error:", err);
    }
  };
  
  // ✅ BƯỚC 1: ĐẢM BẢO HÀM NÀY TỒN TẠI
  // Hàm này chịu trách nhiệm gọi API để lưu một ghi chú mới
  const handleAddActivity = async (leadId, activityData) => {
    try {
      const res = await api.post(`/api/leads/${leadId}/activities`, activityData);
      const newActivity = res.data;
      
      // Cập nhật lại state `leads` để giao diện hiển thị ghi chú mới ngay lập tức
      setLeads(prevLeads => prevLeads.map(l => {
        if (l._id === leadId) {
          // Cập nhật cả editingLead để modal cũng được cập nhật
          setEditingLead(prevEditing => ({...prevEditing, activities: [...(prevEditing.activities || []), newActivity]}));
          return { ...l, activities: [...(l.activities || []), newActivity] };
        }
        return l;
      }));
    } catch (err) {
      console.error("Error adding activity:", err);
      throw err; // Ném lỗi ra để component con (modal) có thể xử lý
    }
  };

  return (
    <div className="p-6 bg-gray-100 min-h-screen relative">
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-2xl font-semibold text-gray-700">📊 Quản lý Leads</h2>
        <div className="header-leads">
          <button className="button-new" onClick={() => setShowAddForm(true)}>+ New</button>
          <div className="view-buttons">
            <button onClick={() => setView("kanban")} className={`button-view ${view === "kanban" ? "active" : ""}`}>🧩 Kanban</button>
            <button onClick={() => setView("list")} className={`button-view ${view === "list" ? "active" : ""}`}>📋 List</button>
          </div>
        </div>
      </div>

      {view === "kanban" ? (
        <LeadKanban leads={leads} onDelete={handleDeleteLead} onDrop={onDrop} onEdit={setEditingLead} />
      ) : (
        <LeadList leads={leads} onDelete={handleDeleteLead} onEdit={setEditingLead} />
      )}

      {showAddForm && <LandingFormModal onAdd={handleAddLead} onClose={() => setShowAddForm(false)} />}
      
      {editingLead && (
        <LeadEditModal
          lead={editingLead}
          onClose={() => setEditingLead(null)}
          onSave={handleSaveEdit}
          // ✅ BƯỚC 2: TRUYỀN HÀM handleAddActivity VÀO PROP onAddActivity
          onAddActivity={handleAddActivity}
        />
      )}
    </div>
  );
};

export default Leads;
